add_action( 'woocommerce_cart_calculate_fees', 'perfectpixel_discount_by_country' );

function perfectpixel_discount_by_country( $cart ) {
	if ( is_admin() && ! defined( 'DOING_AJAX' ) ) {
		return;
	}

	// Billing country (ISO code) => discount percentage.
	$discounts = array(
		'IN' => 50,
		'BR' => 40,
		'EG' => 50,
	);

	$country = WC()->customer ? WC()->customer->get_billing_country() : '';
	if ( empty( $discounts[ $country ] ) ) {
		return;
	}

	$discount = $cart->get_subtotal() * $discounts[ $country ] / 100;
	if ( $discount > 0 ) {
		$cart->add_fee( '{{ppp_label}} (' . $discounts[ $country ] . '%)', -$discount, true );
	}
}
